var t=`0786-rougaille`;var n=`world-0786`;var a=`MU`;var o=`eastern-africa`;var s=4;var r=34;var l={en:`Rougaille`,ua:`Ругай`};var g={en:`Rougaille is a Mauritius classic prepared with yellow onion, garlic, ginger root, tomato. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Ругай, страва кухні країни Маврикій зі складниками: жовта цибуля, часник, корінь імбиру, помідор. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var u=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,190,`g`],[`garlic`,4,`clove`],[`ginger-root`,22,`g`],[`sunflower-oil`,45,`ml`]]},{en:`Simmer the liquid and flavorings uncovered for about 18 minutes until reduced and concentrated.`,ua:`Уварюйте рідину з приправами без кришки приблизно 18 хвилин до насичення та загустіння.`,t:[`reducing-sauce`],m:18,i:[[`tomato`,590,`g`],[`dried-thyme`,4,`g`],[`scotch-bonnet-pepper`,1,`pcs`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`cilantro`,24,`g`],[`table-salt`,null,`to_taste`]]}];var d={slug:t,id:n,country:`MU`,region:o,servings:4,minutes:34,title:l,text:g,steps:u};export{a as country,d as default,n as id,r as minutes,o as region,s as servings,t as slug,u as steps,g as text,l as title};